import { create_organization_prefixs } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    addPrefixDialog: Boolean,
    prefixData: String
  },
  data() {
    return {
      prefix: "",
      prefixRules: [v => !!v || "Prefix is required", v => /^[A-Z0-9]+$/.test(v) || "Only letters and numbers allowed", v => v.length >= 3 || "Minimum 3 characters", v => v.length <= 5 || "Maximum 5 characters"],
      loading: false
    };
  },
  watch: {
    addPrefixDialog: {
      immediate: true,
      async handler() {
        const preData = this.prefixData;
        this.prefix = preData || "";
        // console.log("Prefix initialized as:", this.prefix);
      }
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
      // this.$refs.form.reset();
    },
    async validateAndsave() {
      const {
        valid
      } = await this.$refs.form.validate();
      if (valid) {
        this.Add_Prefix();
      }
    },
    async Add_Prefix() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(create_organization_prefixs, {
          input: {
            organization_id: data.organization.organization_id,
            prefix_name: this.prefix,
            prefix_type: "VENDOR"
          }
        }));
        var response = JSON.parse(result.data.create_organization_prefixs);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.$emit("errorMsg", error.errors[0].message);
        this.loading = false;
      }
    }
  }
};
